import json, urllib.request, urllib.parse, time

def get(url, hdrs=None):
    h = {"User-Agent":"Mozilla/5.0"}
    if hdrs: h.update(hdrs)
    req = urllib.request.Request(url, headers=h)
    return urllib.request.urlopen(req, timeout=45).read().decode("utf-8","replace")

# Semantic Scholar by DOI (with retries) -> openAccessPdf
DOIS = {
 "McNamara2006_JECR": "10.2190/1RU5-HDTJ-A5C8-JVWE",
 "Magliano2005_JECR": "10.2190/1LN8-7BQE-8TN0-M91L",
 "Jackson2013_JEP":   "10.1037/a0032580",
 "Kurby2012_JECR":    "10.2190/EC.47.4.e",
}
for name, doi in DOIS.items():
    ok = False
    for attempt in range(4):
        try:
            d = json.loads(get("https://api.semanticscholar.org/graph/v1/paper/DOI:" + doi +
                               "?fields=title,year,abstract,openAccessPdf,externalIds"))
            oa = d.get("openAccessPdf") or {}
            print("S2", name, "| OA_PDF=", oa.get("url"))
            ab = (d.get("abstract") or "")
            print("   ABSTRACT:", ab[:1500] if ab else "(none)")
            ok = True; break
        except Exception as e:
            time.sleep(12)
    if not ok: print("S2", name, "FAILED after retries")
    time.sleep(3)
print("COREDONE")

